def deleteNode(root, key):
    vals, st, cur = [], [], root
    while st or cur:
        while cur:
            st.append(cur)
            cur = cur.left
        cur = st.pop()
        vals.append(cur.val)
        cur = cur.right
    vals = [v for v in vals if v != key]
    def build(lo, hi):
        if lo > hi:
            return None
        mid = (lo + hi) // 2
        n = TreeNode(vals[mid])
        n.left = build(lo, mid - 1)
        n.right = build(mid + 1, hi)
        return n
    return build(0, len(vals) - 1)

